public class PaymentTerms {
    private static final Pattern NET_TERMS_PATTERN = Pattern.compile('(?i)^NET\\s*(\\d{1,3})$');

    public static Integer parseNetDays(String terms) {
        if (terms == null || terms.trim().length() == 0) {
            throw new UnsupportedTermsException('Unsupported payment terms: ' + terms);
        }

        String normalized = terms.trim();

        if (normalized.equalsIgnoreCase('DUE ON RECEIPT')) {
            return 0;
        }

        Matcher matcher = NET_TERMS_PATTERN.matcher(normalized);
        if (matcher.matches()) {
            Integer days = Integer.valueOf(matcher.group(1));

            if (days > 180) {
                throw new TermsOutOfRangeException('Net days out of range: ' + days);
            }

            return days;
        }

        throw new UnsupportedTermsException('Unsupported payment terms: ' + terms);
    }

    public static Date dueDate(Date invoiceDate, String terms) {
        return invoiceDate.addDays(parseNetDays(terms));
    }
}
