public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    private static final Integer MIN_LIMIT = 1;
    private static final Integer MAX_LIMIT = 200;
    private static final String ID_FIELD = 'Id';

    @AuraEnabled
    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        try {
            return searchInternal(objectApiName, fields, filters, orderByField, maxRows);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            String message = e.getMessage();
            if (String.isBlank(message)) {
                message = e.getTypeName();
            }
            throw new SearchException(message);
        }
    }

    private static List<SObject> searchInternal(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        validateBasicInput(fields, maxRows);

        Schema.SObjectType objectType = findSObjectType(objectApiName);
        if (objectType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
        if (!objectDescribe.isAccessible()) {
            throw new SearchException('Object is not accessible: ' + objectApiName);
        }

        Map<String, Schema.SObjectField> fieldMap = buildFieldMap(objectDescribe);
        validateIdFieldAccess(fieldMap);

        List<String> selectFields = new List<String>{ID_FIELD};
        Set<String> seenFields = new Set<String>{ID_FIELD.toLowerCase()};

        for (String requestedField : fields) {
            if (String.isBlank(requestedField)) {
                throw new SearchException('Field name cannot be blank');
            }

            Schema.SObjectField field = getFieldCaseInsensitive(fieldMap, requestedField);
            if (field == null) {
                throw new SearchException('Field does not exist: ' + requestedField);
            }

            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('Field is not accessible: ' + requestedField);
            }

            String actualFieldName = fieldDescribe.getName();
            String actualFieldNameLower = actualFieldName.toLowerCase();
            if (!seenFields.contains(actualFieldNameLower)) {
                seenFields.add(actualFieldNameLower);
                selectFields.add(actualFieldName);
            }
        }

        Map<String, Object> bindVariables = new Map<String, Object>();
        String whereClause = buildWhereClause(fieldMap, filters, bindVariables);
        String orderByClause = buildOrderByClause(fieldMap, orderByField);

        String query = 'SELECT ' + String.join(selectFields, ', ')
            + ' FROM ' + objectDescribe.getName()
            + whereClause
            + orderByClause
            + ' LIMIT ' + maxRows;

        return Database.queryWithBinds(query, bindVariables, System.AccessLevel.USER_MODE);
    }

    private static void validateBasicInput(List<String> fields, Integer maxRows) {
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be specified');
        }

        if (maxRows == null || maxRows < MIN_LIMIT || maxRows > MAX_LIMIT) {
            throw new SearchException('maxRows must be between ' + MIN_LIMIT + ' and ' + MAX_LIMIT);
        }
    }

    private static Schema.SObjectType findSObjectType(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            return null;
        }

        String lowerCaseName = objectApiName.toLowerCase();
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();

        for (String apiName : globalDescribe.keySet()) {
            if (apiName.toLowerCase().equals(lowerCaseName)) {
                return globalDescribe.get(apiName);
            }
        }

        return null;
    }

    private static Map<String, Schema.SObjectField> buildFieldMap(Schema.DescribeSObjectResult objectDescribe) {
        Map<String, Schema.SObjectField> fieldMap = new Map<String, Schema.SObjectField>();

        for (Schema.SObjectField field : objectDescribe.fields.getMap().values()) {
            fieldMap.put(field.getDescribe().getName().toLowerCase(), field);
        }

        return fieldMap;
    }

    private static Schema.SObjectField getFieldCaseInsensitive(Map<String, Schema.SObjectField> fieldMap, String fieldName) {
        if (String.isBlank(fieldName)) {
            return null;
        }

        return fieldMap.get(fieldName.toLowerCase());
    }

    private static void validateIdFieldAccess(Map<String, Schema.SObjectField> fieldMap) {
        Schema.SObjectField idField = getFieldCaseInsensitive(fieldMap, ID_FIELD);

        if (idField == null || !idField.getDescribe().isAccessible()) {
            throw new SearchException('Cannot read field: ' + ID_FIELD);
        }
    }

    private static String buildWhereClause(Map<String, Schema.SObjectField> fieldMap, Map<String, Object> filters, Map<String, Object> bindVariables) {
        if (filters == null || filters.isEmpty()) {
            return '';
        }

        List<String> filterKeys = new List<String>(filters.keySet());
        for (String key : filterKeys) {
            if (String.isBlank(key)) {
                throw new SearchException('Filter field name cannot be blank');
            }
        }

        filterKeys.sort();

        List<String> conditions = new List<String>();
        Integer bindIndex = 0;

        for (String key : filterKeys) {
            Schema.SObjectField field = getFieldCaseInsensitive(fieldMap, key);
            if (field == null) {
                throw new SearchException('Field does not exist: ' + key);
            }

            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('Field is not accessible: ' + key);
            }

            if (!fieldDescribe.isFilterable()) {
                throw new SearchException('Field cannot be filtered: ' + key);
            }

            Object value = filters.get(key);
            String actualFieldName = fieldDescribe.getName();

            if (value == null) {
                conditions.add(actualFieldName + ' = NULL');
            } else {
                String bindKey = 'p' + bindIndex;
                bindIndex++;
                conditions.add(actualFieldName + ' = :' + bindKey);
                bindVariables.put(bindKey, value);
            }
        }

        return ' WHERE ' + String.join(conditions, ' AND ');
    }

    private static String buildOrderByClause(Map<String, Schema.SObjectField> fieldMap, String orderByField) {
        if (String.isBlank(orderByField)) {
            return '';
        }

        Schema.SObjectField field = getFieldCaseInsensitive(fieldMap, orderByField);
        if (field == null) {
            throw new SearchException('Field does not exist: ' + orderByField);
        }

        Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
        if (!fieldDescribe.isAccessible()) {
            throw new SearchException('Field is not accessible: ' + orderByField);
        }

        if (!fieldDescribe.isSortable()) {
            throw new SearchException('Field cannot be sorted: ' + orderByField);
        }

        return ' ORDER BY ' + fieldDescribe.getName() + ' ASC';
    }
}
