public class OrderPayloadParser {
    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Order payload body is required.');
        }

        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Order payload body is not valid JSON.');
        }

        if (!(root instanceof Map<String,Object>)) {
            throw new PayloadException('Order payload must be a JSON object.');
        }

        Map<String,Object> rootMap = (Map<String,Object>) root;

        Object numberValue = rootMap.get('number');
        if (numberValue == null || String.isBlank(String.valueOf(numberValue))) {
            throw new PayloadException('Order number is required.');
        }
        String orderNumber = String.valueOf(numberValue);

        Order order = new Order();
        order.orderNumber = orderNumber;
        order.lines = new List<Line>();

        Object dateValue = rootMap.get('date');
        if (dateValue != null) {
            try {
                order.orderDate = Date.valueOf(String.valueOf(dateValue));
            } catch (Exception e) {
                throw new PayloadException('Order date has an invalid format.');
            }
        }

        Object currencyValue = rootMap.get('currency');
        if (currencyValue != null) {
            order.currencyCode = String.valueOf(currencyValue);
        }

        Object customerValue = rootMap.get('customer');
        if (customerValue instanceof Map<String,Object>) {
            Map<String,Object> customerMap = (Map<String,Object>) customerValue;
            Object emailValue = customerMap.get('email');
            if (emailValue != null) {
                order.customerEmail = String.valueOf(emailValue);
            }
        }

        Object linesValue = rootMap.get('lines');
        if (linesValue != null) {
            if (!(linesValue instanceof List<Object>)) {
                throw new PayloadException('Order lines must be a JSON array.');
            }
            for (Object lineValue : (List<Object>) linesValue) {
                if (!(lineValue instanceof Map<String,Object>)) {
                    throw new PayloadException('Each order line must be a JSON object.');
                }
                order.lines.add(parseLine((Map<String,Object>) lineValue));
            }
        }

        Decimal total = 0;
        for (Line line : order.lines) {
            total += line.lineTotal;
        }
        order.total = total.setScale(2, System.RoundingMode.HALF_UP);

        return order;
    }

    private static Line parseLine(Map<String,Object> lineMap) {
        Line line = new Line();

        Object skuValue = lineMap.get('sku');
        if (skuValue == null || String.isBlank(String.valueOf(skuValue))) {
            throw new PayloadException('Line SKU is required.');
        }
        line.sku = String.valueOf(skuValue);

        Object quantityValue = lineMap.get('quantity');
        if (quantityValue == null) {
            throw new PayloadException('Line quantity is required.');
        }
        Decimal quantityDecimal = toDecimal(quantityValue);
        if (quantityDecimal == null || quantityDecimal <= 0) {
            throw new PayloadException('Line quantity must be positive.');
        }
        if (quantityDecimal != quantityDecimal.round(System.RoundingMode.DOWN)) {
            throw new PayloadException('Line quantity must be an integer.');
        }
        line.quantity = quantityDecimal.intValue();

        Object unitPriceValue = lineMap.get('unitPrice');
        if (unitPriceValue == null) {
            throw new PayloadException('Line unitPrice is required.');
        }
        Decimal unitPriceDecimal = toDecimal(unitPriceValue);
        if (unitPriceDecimal == null || unitPriceDecimal < 0) {
            throw new PayloadException('Line unitPrice cannot be negative.');
        }
        line.unitPrice = unitPriceDecimal;

        Object discountValue = lineMap.get('discount');
        Decimal discountDecimal = 0;
        if (discountValue != null) {
            discountDecimal = toDecimal(discountValue);
            if (discountDecimal == null || discountDecimal < 0 || discountDecimal > 1) {
                throw new PayloadException('Line discount must be between 0 and 1.');
            }
        }
        line.discount = discountDecimal;

        Decimal lineTotalBase = quantityDecimal * unitPriceDecimal * (1 - discountDecimal);
        line.lineTotal = lineTotalBase.setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    private static Decimal toDecimal(Object value) {
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof String) {
            try {
                return Decimal.valueOf((String) value);
            } catch (Exception e) {
                return null;
            }
        }
        return null;
    }

    public static String toAcknowledgement(Order order) {
        Map<String,Object> ack = new Map<String,Object>();
        if (order == null) {
            ack.put('number', null);
            ack.put('status', 'RECEIVED');
            ack.put('lineCount', 0);
            ack.put('total', 0);
        } else {
            ack.put('number', order.orderNumber);
            ack.put('status', 'RECEIVED');
            ack.put('lineCount', order.lines != null ? order.lines.size() : 0);
            ack.put('total', order.total != null ? order.total : 0);
        }
        return JSON.serialize(ack);
    }
}
