public class LogPurgeJob implements Schedulable, Database.Batchable<FB_Integration_Log__c> {
    public static final Integer BATCH_SIZE = 50;
    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final String CRON_EXP = '0 0 2 * * ?';

    public LogPurgeJob() {}

    public void execute(SchedulableContext ctx) {
        Database.executeBatch(this, BATCH_SIZE);
    }

    public Database.QueryLocator start(Database.BatchableContext ctx) {
        Date thirtyDaysAgo = Date.today().addDays(-30);
        Date oneEightyDaysAgo = Date.today().addDays(-180);

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c != 'ERROR' AND CreatedDate < :thirtyDaysAgo)
               OR (Level__c = 'ERROR' AND CreatedDate < :oneEightyDaysAgo)
               OR (Level__c = null AND CreatedDate < :thirtyDaysAgo)
        ]);
    }

    public void execute(Database.BatchableContext ctx, List<FB_Integration_Log__c> scope) {
        delete scope;
    }

    public void finish(Database.BatchableContext ctx) {}

    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_EXP, new LogPurgeJob());
    }
}
