        System.assertEquals('Closed Lost', stale2.StageName);
        System.assertEquals(OpportunityCleanupService.LOST_REASON, stale2.Description);

        System.assertEquals('Closed Won', closedWon.StageName);
        System.assertEquals(null, closedWon.Description);
        System.assertEquals('Closed Lost', closedLost.StageName);
        System.assertEquals(null, closedLost.Description);
        System.assertEquals('Prospecting', onCutoff.StageName);
        System.assertEquals(null, onCutoff.Description);
        System.assertEquals('Prospecting', later.StageName);
        System.assertEquals(null, later.Description);
        System.assertEquals('Prospecting', nullCloseDate.StageName);
        System.assertEquals(null, nullCloseDate.Description);

        ((IOpportunitiesSelector) mocks.verify(mockSelector, mocks.times(1)))
            .selectById(ids);

        fflib_ArgumentCaptor dirtyCaptor = new fflib_ArgumentCaptor();
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.times(2)))
            .registerDirty((SObject) dirtyCaptor.capture());

        List<Object> registeredRecords = dirtyCaptor.getAllValues();
        System.assertEquals(2, registeredRecords.size());

        Set<Id> registeredIds = new Set<Id>();
        for (Object registeredRecord : registeredRecords) {
            Opportunity registered = (Opportunity) registeredRecord;
            registeredIds.add(registered.Id);
            System.assertEquals('Closed Lost', registered.StageName);
            System.assertEquals(OpportunityCleanupService.LOST_REASON, registered.Description);
        }
        System.assertEquals(new Set<Id>{stale1Id, stale2Id}, registeredIds);

        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.times(1))).commitWork();
    }
