    public List<Schema.SObjectField> getSObjectFieldList()
    {
        List<Schema.SObjectField> fieldList = new List<Schema.SObjectField>
        {
            Account.Id,
            Account.Name,
            Account.Industry
        };

        Set<Schema.SObjectField> uniqueFields = new Set<Schema.SObjectField>(fieldList);
        Schema.DescribeSObjectResult accountDescribe = Account.SObjectType.getDescribe();

        for (Schema.FieldSet fieldSet : accountDescribe.fieldSets.getMap().values())
        {
            if (fieldSet.getName() == 'Credit_Review')
            {
                for (Schema.FieldSetMember member : fieldSet.getFields())
                {
                    Schema.SObjectField field = member.getSObjectField();
                    if (!uniqueFields.contains(field))
                    {
                        fieldList.add(field);
                        uniqueFields.add(field);
                    }
                }
                break;
            }
        }

        return fieldList;
    }

    public List<Account> selectById(Set<Id> accountIds)
    {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds)
    {
        if (accountIds == null || accountIds.isEmpty())
        {
            return new List<Account>();
        }

        ContactsSelector contactSelector = new ContactsSelector();
        List<String> contactFieldNames = new List<String>();

        for (Schema.SObjectField contactField : contactSelector.getSObjectFieldList())
        {
            contactFieldNames.add(contactField.getDescribe().getName());
        }

        String contactsSubquery = 'SELECT ' + String.join(contactFieldNames, ', ') + ' FROM Contacts';

        fflib_QueryFactory queryFactory = newQueryFactory();
        queryFactory.selectField('(' + contactsSubquery + ')');
        queryFactory.setCondition('Id IN :accountIds');

        return (List<Account>) Database.query(queryFactory.toSOQL());
    }
