trigger CaseTrigger on Case (after update) {
    List<Id> eligibleCaseIds = new List<Id>();

    for (Case currentCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(currentCase.Id);

        if (oldCase == null) {
            continue;
        }

        Boolean changedToClosed = !oldCase.IsClosed && currentCase.IsClosed;
        Boolean hasContact = currentCase.ContactId != null;

        if (changedToClosed && hasContact) {
            eligibleCaseIds.add(currentCase.Id);
        }
    }

    if (!eligibleCaseIds.isEmpty()) {
        /*
         * Bulk-safe change:
         * Originally planned as "one job per case", but that exceeds the 50
         * Queueable enqueues per transaction limit when 200 cases are closed
         * in a single bulk operation (nightly cleanup).
         * Instead, enqueue ONE job with the full list of eligible case IDs.
         * The job uses Database.insert(..., false) to isolate any per-record
         * failure, so one failure cannot affect the others.
         */
        System.enqueueJob(new CaseSurveyJob(eligibleCaseIds));
    }
}
