public class CaseSurveyJob implements Queueable {
    private List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext context) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> eligibleCases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
              AND IsClosed = true
              AND ContactId != null
        ];

        List<Task> tasksToInsert = new List<Task>();

        for (Case currentCase : eligibleCases) {
            Task surveyTask = new Task(
                WhatId = currentCase.Id,
                WhoId = currentCase.ContactId,
                Subject = 'CSAT survey: ' + currentCase.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status = 'Not Started'
            );
            tasksToInsert.add(surveyTask);
        }

        if (!tasksToInsert.isEmpty()) {
            // Partial success ensures one failing task does not prevent others.
            Database.insert(tasksToInsert, false);
        }
    }
}
