import { LightningElement, api, track } from 'lwc';

let instanceCounter = 0;

export default class StatusListbox extends LightningElement {
  @api label;

  @track _options = [];
  @track _value = '';
  @track _activeIndex = -1;
  _idPrefix;

  constructor() {
    super();
    this._idPrefix = `status-listbox-${++instanceCounter}`;
  }

  @api
  get options() {
    return this._options;
  }

  set options(value) {
    this._options = Array.isArray(value) ? value : [];
    this.syncActiveToSelected();
  }

  @api
  get value() {
    return this._value;
  }

  set value(value) {
    this._value = value === undefined || value === null ? '' : value;
    this.syncActiveToSelected();
  }

  get computedOptions() {
    return this._options.map((option, index) => {
      const isSelected = option.value === this._value;
      return {
        ...option,
        id: `${this._idPrefix}-option-${index}`,
        index,
        ariaSelected: isSelected ? 'true' : 'false',
      };
    });
  }

  get activeDescendantId() {
    if (
      this._options.length === 0 ||
      this._activeIndex < 0 ||
      this._activeIndex >= this._options.length
    ) {
      return '';
    }
    return `${this._idPrefix}-option-${this._activeIndex}`;
  }

  handleKeydown(event) {
    const key = event.key;

    if (
      key === 'ArrowDown' ||
      key === 'ArrowUp' ||
      key === 'Home' ||
      key === 'End' ||
      key === 'Enter' ||
      key === ' '
    ) {
      event.preventDefault();
    } else {
      return;
    }

    if (this._options.length === 0) {
      return;
    }

    switch (key) {
      case 'ArrowDown':
        this._activeIndex = Math.min(
          this._options.length - 1,
          this._activeIndex + 1
        );
        break;
      case 'ArrowUp':
        this._activeIndex = Math.max(0, this._activeIndex - 1);
        break;
      case 'Home':
        this._activeIndex = 0;
        break;
      case 'End':
        this._activeIndex = this._options.length - 1;
        break;
      case 'Enter':
      case ' ':
        this.selectActive();
        break;
      default:
        // No other handled keys.
    }
  }

  handleOptionClick(event) {
    const value = event.currentTarget.dataset.value;
    if (value === undefined || value === null) {
      return;
    }

    const index = this._options.findIndex((option) => option.value === value);
    if (index === -1) {
      return;
    }

    this._activeIndex = index;

    const list = this.template.querySelector('ul');
    if (list) {
      list.focus();
    }

    this.selectActive();
  }

  selectActive() {
    if (
      this._options.length === 0 ||
      this._activeIndex < 0 ||
      this._activeIndex >= this._options.length
    ) {
      return;
    }

    const option = this._options[this._activeIndex];
    if (option.value === this._value) {
      return;
    }

    this.dispatchEvent(
      new CustomEvent('change', {
        detail: { value: option.value },
        bubbles: true,
        composed: true,
      })
    );
  }

  syncActiveToSelected() {
    const selectedIndex = this._options.findIndex(
      (option) => option.value === this._value
    );

    if (selectedIndex !== -1) {
      this._activeIndex = selectedIndex;
    } else if (this._options.length > 0) {
      this._activeIndex = 0;
    } else {
      this._activeIndex = -1;
    }
  }
}
