        for (SoftCreditRequest req : requests) {
            if (req == null) {
                throw new SoftCreditException('Request cannot be null.');
            }
            if (req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Opportunity and Contact are required.');
            }
            if (String.isBlank(req.role)) {
                throw new SoftCreditException('Role is required.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive.');
            }

            String key = makeKey(req.opportunityId, req.contactId);
            if (requestByKey.containsKey(key)) {
                throw new SoftCreditException('Duplicate Opportunity/Contact pair in request.');
            }
            requestByKey.put(key, req);
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

