public with sharing class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('contactId is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('giftDate is required.');
        }

        List<Contact> primaryContacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];

        if (primaryContacts.isEmpty()) {
            throw new IllegalArgumentException('Contact not found: ' + contactId);
        }

        Contact primary = primaryContacts[0];

        if (primary.AccountId == null) {
            throw new IllegalArgumentException('Contact is not associated with a household account: ' + contactId);
        }

        Savepoint sp = Database.setSavepoint();

        try {
            String formattedDate = DateTime.newInstance(giftDate, Time.newInstance(0, 0, 0, 0))
                .format('yyyy-MM-dd');
            String firstName = String.isBlank(primary.FirstName) ? '' : primary.FirstName.trim();
            String lastName = String.isBlank(primary.LastName) ? '' : primary.LastName.trim();
            String fullName = (firstName + ' ' + lastName).trim();
            String opportunityName = fullName + ' Donation ' + formattedDate;

            Opportunity donation = new Opportunity(
                Name = opportunityName,
                AccountId = primary.AccountId,
                npsp__Primary_Contact__c = primary.Id,
                CloseDate = giftDate,
                StageName = 'Closed Won',
                Amount = amount
            );

            insert donation;

            List<Contact> householdMembers = [
                SELECT Id
                FROM Contact
                WHERE AccountId = :primary.AccountId
            ];

            List<OpportunityContactRole> existingRoles = [
                SELECT Id, ContactId, Role, IsPrimary
                FROM OpportunityContactRole
                WHERE OpportunityId = :donation.Id
            ];

            Map<Id, OpportunityContactRole> roleByContactId = new Map<Id, OpportunityContactRole>();
            for (OpportunityContactRole ocr : existingRoles) {
                roleByContactId.put(ocr.ContactId, ocr);
            }

            List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
            List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();

            for (Contact member : householdMembers) {
                OpportunityContactRole existing = roleByContactId.get(member.Id);

                if (member.Id == primary.Id) {
                    if (existing != null) {
                        existing.Role = 'Donor';
                        existing.IsPrimary = true;
                        rolesToUpdate.add(existing);
                    } else {
                        rolesToInsert.add(new OpportunityContactRole(
                            OpportunityId = donation.Id,
                            ContactId = primary.Id,
                            Role = 'Donor',
                            IsPrimary = true
                        ));
                    }
                } else {
                    if (existing == null) {
                        rolesToInsert.add(new OpportunityContactRole(
                            OpportunityId = donation.Id,
                            ContactId = member.Id,
                            Role = 'Household Member',
                            IsPrimary = false
                        ));
                    } else if (existing.Role != 'Household Member' || existing.IsPrimary != false) {
                        existing.Role = 'Household Member';
                        existing.IsPrimary = false;
                        rolesToUpdate.add(existing);
                    }
                }
            }

            if (!rolesToInsert.isEmpty()) {
                insert rolesToInsert;
            }
            if (!rolesToUpdate.isEmpty()) {
                update rolesToUpdate;
            }

            npe01__OppPayment__c payment = new npe01__OppPayment__c();
            payment.npe01__Opportunity__c = donation.Id;
            payment.npe01__Payment_Amount__c = amount;
            payment.npe01__Payment_Date__c = giftDate;
            payment.npe01__Scheduled_Date__c = giftDate;
            payment.npe01__Paid__c = true;
            insert payment;

            return donation.Id;
        } catch (Exception e) {
            Database.rollback(sp);
