public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject obj : triggerNew) {
            Contact con = (Contact) obj;

            if (con.AccountId == null) {
                continue;
            }

            Boolean allMailingFieldsBlank =
                String.isBlank(con.MailingStreet) &&
                String.isBlank(con.MailingCity) &&
                String.isBlank(con.MailingPostalCode) &&
                String.isBlank(con.MailingCountry);

            if (!allMailingFieldsBlank) {
                continue;
            }

            Account acct = accountsById.get(con.AccountId);

            if (acct == null) {
                continue;
            }

            con.MailingStreet = acct.BillingStreet;
            con.MailingCity = acct.BillingCity;
            con.MailingPostalCode = acct.BillingPostalCode;
            con.MailingCountry = acct.BillingCountry;
        }
    }
}
